\label{thm:main}
There exist geometric $(23_4)$ configurations, as follows.
\begin{enumerate}
\item[(A)] In homogeneous coordinates $(x:y:z)$, let $\mathcal{P}_A$ consist of the $23$ points
\begin{equation}\label{eq:pointsA}
\begin{gathered}
(1{:}0{:}0),\quad (0{:}1{:}{\pm}1),\quad (0{:}3{:}{\pm}2),\quad (1{:}{\pm}1{:}0),\\
(3{:}{\pm}2{:}{\pm}2),\quad (2{:}{\pm}3{:}{\pm}2),\quad (6{:}{\pm}1{:}{\pm}2),\quad (6{:}{\pm}5{:}{\pm}2),
\end{gathered}
\end{equation}
and let $\mathcal{L}_A$ consist of the $23$ lines
\begin{equation}\label{eq:linesA}
\begin{gathered}
x=0,\quad y\pm z=0,\quad 2y\pm3z=0,\quad x\pm3z=0,\\
x\pm2y\pm2z=0,\quad 2x\pm6y\pm9z=0,\quad 2x\pm2y\pm z=0,\quad 2x\pm2y\pm5z=0,
\end{gathered}
\end{equation}
where all sign combinations are taken.  Then $(\mathcal{P}_A,\mathcal{L}_A)$ is a geometric $(23_4)$ configuration.
\item[(B)] Let $\tau=\sqrt{(1+\sqrt{17})/4}\approx 1.1317139$, so that $2\tau^4-\tau^2-2=0$ and $\tau^{-1}=\sqrt{(\sqrt{17}-1)/4}$.  In an affine chart of the real projective plane with coordinates $(X,Z)$, let $\mathcal{P}_B$ consist of the point $O_1$ at infinity in the direction of the $X$-axis together with the $22$ finite points
\begin{equation}\label{eq:points}
\begin{gathered}
(0,\pm\tau),\quad (0,\pm\tau^{-1}),\quad (\pm 2,\,0),\\
(\pm 1,\ \pm(\tau+\tau^{-1})),\quad (\pm 2\tau^{2},\ \pm\tau),\quad
(\pm 1,\ \pm(\tau-\tau^{-1})),\quad (\pm 2\tau^{-2},\ \pm\tau^{-1}),
\end{gathered}
\end{equation}
and let $\mathcal{L}_B$ consist of the polar lines of the points of $\mathcal{P}_B$ with respect to the conic $X^2-2Z^2=2$ (that is, the line $X_0X-2Z_0Z=2$ for a finite point $(X_0,Z_0)$, and the line $X=0$ for $O_1$).  Then $(\mathcal{P}_B,\mathcal{L}_B)$ is a geometric $(23_4)$ configuration.  It is defined over $\mathbb{Q}(\sqrt{17})$, because the substitution $Z\mapsto\tau Z$ turns it into the configuration whose finite points are
\begin{equation}\label{eq:points17}
\begin{gathered}
(0,\pm1),\quad \Bigl(0,\pm\tfrac{\sqrt{17}-1}{4}\Bigr),\quad(\pm2,0),\quad \Bigl(\pm1,\pm\tfrac{3+\sqrt{17}}{4}\Bigr),\\
\Bigl(\pm\tfrac{1+\sqrt{17}}{2},\pm1\Bigr),\quad \Bigl(\pm1,\pm\tfrac{5-\sqrt{17}}{4}\Bigr),\quad \Bigl(\pm\tfrac{\sqrt{17}-1}{2},\pm\tfrac{\sqrt{17}-1}{4}\Bigr),
\end{gathered}
\end{equation}
self-polar with respect to the conic $X^2-\frac{1+\sqrt{17}}{2}Z^2=2$.  It is not projectively equivalent to a configuration with rational coordinates.
\end{enumerate}
The two configurations are not isomorphic as incidence structures.

\label{prop:norotation}
Let $r\in\operatorname{SO}(3)$ be a rotation of order $m\ge3$, let $O$ and $\ell$ be the point and the line of $\mathbb{P}^2(\mathbb{R})$ fixed by $r$, and let $(\mathcal{P},\mathcal{L})$ be an $r$-invariant geometric $(n_4)$ configuration.  Then $m\le n/2$, and one of the following holds.
\begin{enumerate}
\item[(a)] $O\in\mathcal{P}$, $\ell\in\mathcal{L}$, $m\in\{4,8\}$ and $n\equiv1\pmod4$, and moreover $n\equiv5\pmod8$ if $m=8$.
\item[(b)] $O\notin\mathcal{P}$, $\ell\notin\mathcal{L}$, and $m$ divides $n$ if $m$ is odd, while $m/2$ divides $n$ if $m$ is even.
\end{enumerate}

\label{prop:structure}
After renumbering the coordinates, the following hold.
\begin{enumerate}
\item[(a)] $O_1\in\mathcal{P}$, $O_2,O_3\notin\mathcal{P}$, $\ell_1\in\mathcal{L}$, $\ell_2,\ell_3\notin\mathcal{L}$; the line $\ell_1$ contains exactly two pairs $T_1,T_2$ of $\mathcal{P}$, and the four lines of $\mathcal{L}$ through $O_1$ are exactly the lines $O_1q$, $q\in T_1\cup T_2$.
\item[(b)] A point of $\mathcal{P}$ on $\ell_i$, $i\in\{2,3\}$, other than $O_1$ lies on no line of $\mathcal{L}$ through $O_1$, $O_2$ or $O_3$, and lies on exactly two pairs $\{g,\sigma_ig\}$ of regular lines of $\mathcal{L}$, coming from two different regular orbits.  Dually, a line of $\mathcal{L}$ through $O_2$ or $O_3$ other than $\ell_1$ contains no point of $\mathcal{P}$ on $\ell_1$, $\ell_2$ or $\ell_3$, and contains exactly two pairs of regular points of $\mathcal{P}$, from two different regular orbits.
\item[(c)] $b_2+b_3=\frac{n-5}2-2c$ and $b'_2+b'_3=\frac{n-5}2-2c'$, with $2b_2,2b_3\le c'$ and $2b'_2,2b'_3\le c$.  For $n=23$, $(c,c')\in\{(4,4),(4,3),(3,4)\}$; if $c=4$ then $b_2+b_3=1$, and if $c=3$ then $\{b_2,b_3\}=\{1,2\}$; dually for $c'$ and $b'_2,b'_3$.
\end{enumerate}

\label{lem:local}
\begin{enumerate}
\item[(i)] $O_1$ lies exactly on $m_1,m_1',m_2,m_2'$; each $q_i$ lies on $\ell_1$, on $m_i$, and on exactly one pair $\{g,\sigma_1g\}$ of regular lines, from one orbit; the orbits attached to $T_1$ and to $T_2$ are different.  Dually, each $m_i$ contains $O_1$, $q_i$ and exactly one pair $\{p,\sigma_1p\}$ of regular points, and the orbits attached to $\{m_1,m_1'\}$ and to $\{m_2,m_2'\}$ are different.
\item[(ii)] Each point of $S$ lies on no line of any pair $\{n_k,n_k'\}$ and on exactly two pairs $\{g,\sigma_Sg\}$ of regular lines from two different orbits, where $\sigma_S$ is the element of $V$ fixing $S$ pointwise.  Dually for the lines $n_k$.
\item[(iii)] A regular point lies on at most one line of each regular orbit and on at most one line through each $O_i$; a regular line contains at most one point of each regular orbit and at most one point on each $\ell_i$.
\item[(iv)] All degrees equal $4$, and no two points lie on two common lines.
\end{enumerate}

\label{prop:solve}
Of the $4021$ quotient structures, $4018$ have no complex solutions, since the saturated ideal $J$ is the unit ideal.  The remaining three are as follows.
\begin{enumerate}
\item[(a)] a structure with $S\subset\ell_3$, $\{n_1,n_1'\}$ through $O_3$, whose two solutions both satisfy $S'_1=1$, which produces an incidence not in the structure; saturating by $1-S'_1$ gives the unit ideal, so it has no realization;
\item[(b)] a structure with $S\subset\ell_3$, $\{n_1,n_1'\}$ through $O_3$, with exactly two nondegenerate solutions, both real and with coordinates in $\mathbb{Q}(\sqrt{17})$; they are conjugate under $\sqrt{17}\mapsto-\sqrt{17}$, and in the normalization $u_1=v_1=1$ they are carried onto the $\mathbb{Q}(\sqrt{17})$-model \eqref{eq:points17} of $(\mathcal{P}_B,\mathcal{L}_B)$ by the diagonal projectivities $\operatorname{diag}\bigl(1,\tfrac{1-\sqrt{17}}{8},\tfrac{1-\sqrt{17}}{8}\bigr)$ and $\operatorname{diag}\bigl(1,-\tfrac{1+\sqrt{17}}{8},-\tfrac12\bigr)$, which we verified on all $23$ points by exact arithmetic;
\item[(c)] a structure with $S\subset\ell_3$, $\{n_1,n_1'\}$ through $O_2$, with exactly one solution, which is rational and nondegenerate, namely
$t_2=u_1=v_1=\tfrac23$, $u_2=-\tfrac32$, $v_2=-1$, $u_3=\tfrac16$, $u_4=-\tfrac56$, $v_3=v_4=-\tfrac13$, $S'_1=3$, $(m_a)=(-2,3,-1,-1)$, $(n_a)=(2,-\tfrac92,-\tfrac12,\tfrac52)$; clearing denominators gives exactly the points \eqref{eq:pointsA} and lines \eqref{eq:linesA}.
\end{enumerate}

\label{thm:22}
Up to projective equivalence there are exactly nine geometric $(22_4)$ configurations with a Klein four-group of symmetries, of five combinatorial types, as follows.
\begin{enumerate}
\item[(i)] the two configurations of Cuntz \cite{Cun18} (the parameter $w=(-7\pm3\sqrt{17})/2$), which are combinatorially isomorphic but projectively inequivalent, and their two duals;
\item[(ii)] a type $T_3$ with one configuration, defined over $\mathbb{Q}(\sqrt3)$, whose points and lines are the $V$-orbits of
\begin{equation}\label{eq:T3}
\begin{gathered}
(0,1,2{+}\sqrt3),\quad (1,0,1{-}\tfrac13\sqrt3),\quad (1,-1{+}\tfrac13\sqrt3,0),\quad (1,1,1),\\
(1,2{-}\sqrt3,2{-}\sqrt3),\quad (1,-1{+}\tfrac23\sqrt3,1),\quad (1,2{-}\sqrt3,-\tfrac13\sqrt3);\\[2pt]
[0,1,-1],\quad [1,0,-1],\quad [1,-2{-}\sqrt3,0],\quad [1,\tfrac92{+}\tfrac52\sqrt3,-\tfrac32{-}\tfrac12\sqrt3],\\
[1,\tfrac32{+}\tfrac12\sqrt3,-\tfrac32{+}\tfrac12\sqrt3],\quad [1,\tfrac12{+}\tfrac12\sqrt3,-\tfrac32{-}\tfrac12\sqrt3],\quad [1,\tfrac32{+}\tfrac12\sqrt3,-\tfrac12{-}\tfrac12\sqrt3]
\end{gathered}
\end{equation}
(the first three points and lines have orbits of size two, the others of size four);
\item[(iii)] a type $T_1$ with two configurations, conjugate under $\sqrt\varphi\mapsto-\sqrt\varphi$ and projectively inequivalent, defined over the quartic field $\mathbb{Q}(\sqrt5,\sqrt\varphi)$, $\varphi=(1+\sqrt5)/2$;  writing $t=\sqrt\varphi$, so that $t^4=t^2+1$, the coordinates of both are polynomials in $t$ with integer coefficients;
\item[(iv)] a type $T_2$ with two configurations, projectively inequivalent, conjugate under $\sqrt2\mapsto-\sqrt2$, defined over $\mathbb{Q}(\sqrt2,\sqrt5)$.
\end{enumerate}
The same nine are the real ones among the $80$ Klein-symmetric $(22_4)$ configurations in the complex projective plane.  None of the nine is definable over $\mathbb{Q}$, the configurations of type $T_1,T_2$ are not definable over $\mathbb{Q}(\sqrt5)$, and all nine have collineation group exactly $V$; the Levi graphs of $T_2$ and $T_3$ have automorphism groups of order $8$, those of $T_1$ and of Cuntz's types of order $4$.

\label{prop:involution}
Let $\mathcal{C}=(\mathcal{P},\mathcal{L})$ be a geometric $(23_4)$ configuration invariant under an involutory collineation $\sigma$, a harmonic homology with centre $O$ and axis $\ell$.  Let $a=[O\in\mathcal{P}]$, $a'=[\ell\in\mathcal{L}]$, let $b$ be the number of points of $\mathcal{P}$ on $\ell$ and $b'$ the number of lines of $\mathcal{L}$ through $O$, and let $c$ and $c'$ be the numbers of pairs $\{p,\sigma p\}$ of points of $\mathcal{P}$ and $\{g,\sigma g\}$ of lines of $\mathcal{L}$ not fixed by $\sigma$.  Then exactly one of the following holds.
\begin{enumerate}
\item[(a)] $a=a'=1$, $b=b'=4$ and $c=c'=9$.  Every point of $\mathcal{P}$ on $\ell$ lies on a line of $\mathcal{L}$ through $O$, every line of $\mathcal{L}$ through $O$ meets $\ell$ in a point of $\mathcal{P}$, and these correspondences are inverse bijections.
\item[(b)] $a=a'=0$, $b$ and $b'$ are odd, $(b,b')$ is one of the eight pairs
\[
(1,1),\ (1,3),\ (1,5),\ (3,1),\ (3,3),\ (3,5),\ (5,1),\ (5,3),
\]
and $c=(23-b)/2$, $c'=(23-b')/2$.  No line of $\mathcal{L}$ through $O$ meets $\ell$ in a point of $\mathcal{P}$; every point of $\mathcal{P}$ on $\ell$ lies on exactly two pairs of lines of $\mathcal{L}$, and every line of $\mathcal{L}$ through $O$ contains exactly two pairs of points of $\mathcal{P}$.
\end{enumerate}

The fixed points of $\sigma$ are $O$ and the points of $\ell$; the fixed lines are $\ell$ and the lines through $O$.  Counting points and lines orbit by orbit gives $23=a+b+2c=a'+b'+2c'$, so $a+b$ and $a'+b'$ are odd.

Let $g$ be a line of $\mathcal{L}$ through $O$.  It is fixed by $\sigma$, and $\sigma$ acts on it as an involution with fixed points $O$ and $g\cap\ell$, so the points of $\mathcal{P}$ on $g$ other than these come in pairs $\{p,\sigma p\}$.  Hence
\begin{equation}\label{eq:linethroughO}
4=a+[\,g\cap\ell\in\mathcal{P}\,]+2k
\end{equation}
for some integer $k\ge0$.  Dually, for a point $q$ of $\mathcal{P}$ on $\ell$, the lines of $\mathcal{L}$ through $q$ other than $\ell$ and $Oq$ come in pairs, so
\begin{equation}\label{eq:pointonell}
4=a'+[\,Oq\in\mathcal{L}\,]+2k'
\end{equation}
for some integer $k'\ge0$.

Suppose first that $a=1$.  The four lines of $\mathcal{L}$ through $O$ are fixed, so $b'=4$, $a'=1$ as $a'+b'$ is odd, and $b=4$ as $\ell\in\mathcal{L}$.  Then $23=1+4+2c$ gives $c=9$, and dually $c'=9$.  By \eqref{eq:linethroughO} with $a=1$, each line $g$ of $\mathcal{L}$ through $O$ satisfies $g\cap\ell\in\mathcal{P}$, and by \eqref{eq:pointonell} with $a'=1$, each point $q$ of $\mathcal{P}$ on $\ell$ satisfies $Oq\in\mathcal{L}$; the maps $g\mapsto g\cap\ell$ and $q\mapsto Oq$ are injective and inverse to each other.  This is case (a).

Suppose next that $a=0$ and $a'=1$.  Then $\ell\in\mathcal{L}$ contains exactly four points of $\mathcal{P}$, so $b=4$ and $a+b$ is even, a contradiction.  So $a=0$ forces $a'=0$, and $b$, $b'$ are odd.  By \eqref{eq:linethroughO} with $a=0$, every line $g$ of $\mathcal{L}$ through $O$ has $g\cap\ell\notin\mathcal{P}$ and contains exactly two pairs of points of $\mathcal{P}$; by \eqref{eq:pointonell} with $a'=0$, every point $q$ of $\mathcal{P}$ on $\ell$ has $Oq\notin\mathcal{L}$ and lies on exactly two pairs $\{g,\sigma g\}$ of lines of $\mathcal{L}$.  A line $g$ not fixed by $\sigma$ does not pass through $O$, and $g\cap\ell$ is fixed by $\sigma$, so $g\cap\ell=\sigma g\cap\ell$ is the unique common point of $g$ and $\sigma g$; thus each pair of lines is attached to exactly one point of $\ell$, and the $2b$ pairs attached to the $b$ points of $\mathcal{P}$ on $\ell$ are distinct.  Hence $2b\le c'=(23-b')/2$, that is, $4b+b'\le23$, and dually $4b'+b\le23$.  The odd positive solutions are exactly the eight pairs in (b).  This is case (b).

\label{thm:selfpolar}
\begin{enumerate}
\item[(a)] There are $52$ pairwise projectively inequivalent self-polar geometric $(23_4)$ configurations with a nontrivial collineation group, namely $(\mathcal{P}_A,\mathcal{L}_A)$ and $(\mathcal{P}_B,\mathcal{L}_B)$, whose group is the Klein four-group, and $50$ configurations whose group has order two.  They have $41$ distinct combinatorial types, and their fields of definition have degrees $1$ to $7$ over $\mathbb{Q}$.  Four of them, $(\mathcal{P}_A,\mathcal{L}_A)$ and three of the new ones, can be defined over $\mathbb{Q}$.
\item[(b)] Every self-polar geometric $(23_4)$ configuration with a nontrivial collineation group is projectively equivalent to one of these $52$, unless one of the $3{,}911{,}385$ systems that are inconsistent modulo both $32003$ and $1{,}000{,}003$ has a solution over $\overline{\mathbb{Q}}$.
\end{enumerate}

\label{thm:third}
Let $\mathcal{P}_N$ consist of the three points $(0{:}1{:}0)$, $(0{:}2{:}{-}3)$, $(0{:}4{:}{-}3)$ and the twenty points $(\pm x{:}y{:}z)$ for $(x{:}y{:}z)$ among
\begin{equation}\label{eq:pointsN}
\begin{gathered}
(1{:}{-}1{:}1),\quad (2{:}{-}1{:}1),\quad (2{:}{-}2{:}1),\quad (2{:}{-}2{:}5),\quad (2{:}{-}7{:}5),\\ (2{:}{-}8{:}5),\quad (4{:}{-}4{:}5),\quad (4{:}{-}6{:}5),\quad (4{:}{-}8{:}5),\quad (8{:}{-}2{:}5),
\end{gathered}
\end{equation}
and let $\mathcal{L}_N$ consist of their polars with respect to the conic $5x^2+20y^2+40yz+16z^2=0$.  Then $(\mathcal{P}_N,\mathcal{L}_N)$ is a geometric $(23_4)$ configuration with integer coordinates, self-polar with respect to a real conic, whose collineation group is $\{1,\sigma\}$ with $\sigma=\operatorname{diag}(-1,1,1)$.  It is the configuration $N_{31}$ of Figure~\ref{fig:gallery}.
